package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the period form: the name is required (no spaces, as it names the period's row and audit
 *  field), the from- and to-date are yyyy-mm-dd and from is on or before to. */
public class ValidatePeriod {
    public void validate(@RequestBody PeriodRequest request, Out<PeriodInput> period) throws BadRequestException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new BadRequestException("name is required");
        }
        if (name.chars().anyMatch(Character::isWhitespace)) {
            throw new BadRequestException("name must not contain spaces");
        }
        if (name.length() > 500) {
            throw new BadRequestException("name is too long");
        }
        LocalDate from = date(request.from(), "from-date");
        LocalDate to = date(request.to(), "to-date");
        if (from.isAfter(to)) {
            throw new BadRequestException("from-date must be on or before to-date");
        }
        period.set(new PeriodInput(name, from, to));
    }

    private static LocalDate date(String value, String what) throws BadRequestException {
        String v = value == null ? "" : value.trim();
        if (v.isEmpty()) {
            throw new BadRequestException(what + " is required");
        }
        try {
            return LocalDate.parse(v);
        } catch (DateTimeParseException e) {
            throw new BadRequestException(what + " must be yyyy-mm-dd");
        }
    }
}
=== java/net/officefloor/hq/app/period/SavePeriod.java
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SavePeriod {
    public void save(@PathVariable("sheetId") String sheetId, @Val PeriodInput input,
            ServerHttpConnection connection, PeriodRepository repository, Audit audit, Out<Period> period)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        if (repository.named(id, input.name())) {
            throw new BadRequestException("a period named " + input.name() + " is already on the sheet");
        }
        if (repository.overlaps(id, input.from(), input.to())) {
            throw new BadRequestException("the period overlaps another period");
        }
        Period saved = repository.add(id, input.name(), input.from(), input.to());
        audit.record("PERIOD_ADDED sheet=" + id + " by=" + by + " period=" + saved.name() + " from=" + saved.from()
                + " to=" + saved.to());
        period.set(saved);
    }
}
